// Package wire converts between the adapter SDK's types (package model) and
// the beenfar.adapter.v1 protobuf messages.
//
// The field-by-field mapping is generated by goverter into gen/ from the
// Converter interface; this file holds the interface and the enum and unit
// rules it calls through `extend`. Both sides of the adapter API use it: the
// controller to serve AdapterHostService and the SDK's RunRemote to call it.
package wire

//go:generate rm -rf gen
//go:generate go run github.com/jmattheis/goverter/cmd/goverter@v1.11.1 gen .

import (
	"time"

	"google.golang.org/protobuf/types/known/timestamppb"

	"github.com/jacobalberty/beenfar/api/adapter/model"
	adapterv1 "github.com/jacobalberty/beenfar/api/gen/go/beenfar/adapter/v1"
)

// Converter is implemented by gen/ (package wiregen) as plain functions.
//
// Field names differ only in initialism case (Id/ID, Ssid/SSID, VlanId/VLANID),
// hence matchIgnoreCase. Protobuf's unexported bookkeeping fields are left
// zero, which is correct for new messages.
//
// goverter:converter
// goverter:output:file ./gen/wire.go
// goverter:output:package github.com/jacobalberty/beenfar/api/adapter/wire/gen:wiregen
// goverter:output:format function
// goverter:matchIgnoreCase
// goverter:ignoreUnexported
// goverter:useZeroValueOnPointerInconsistency
// goverter:extend DeviceStateToProto DeviceStateFromProto WifiSecurityToProto WifiSecurityFromProto
// goverter:extend WifiBandToProto WifiBandFromProto SecondsFromDuration DurationFromSeconds Int32 Int
// goverter:extend TimeToProto TimeFromProto ReadoptionToProto ReadoptionFromProto
type Converter interface {
	// goverter:map LastSeen LastSeenTime
	DeviceToProto(model.Device) *adapterv1.Device
	// goverter:map LastSeenTime LastSeen
	DeviceFromProto(*adapterv1.Device) model.Device

	DiscoveredToProto(model.Discovered) *adapterv1.Discovered
	DiscoveredFromProto(*adapterv1.Discovered) model.Discovered

	// goverter:map Uptime UptimeSeconds | SecondsFromDuration
	StateToProto(model.State) *adapterv1.State
	// goverter:map UptimeSeconds Uptime | DurationFromSeconds
	StateFromProto(*adapterv1.State) model.State

	DesiredConfigToProto(model.DesiredConfig) *adapterv1.DesiredConfig
	DesiredConfigFromProto(*adapterv1.DesiredConfig) model.DesiredConfig
}

// Int32 and Int convert VLAN ids; 802.1Q ids fit in 12 bits.
func Int32(v int) int32 { return int32(v) }
func Int(v int32) int   { return int(v) }

func TimeToProto(t time.Time) *timestamppb.Timestamp {
	if t.IsZero() {
		return nil
	}
	return timestamppb.New(t)
}

func TimeFromProto(t *timestamppb.Timestamp) time.Time {
	if t == nil {
		return time.Time{}
	}
	return t.AsTime()
}

func ReadoptionToProto(r model.Readoption) adapterv1.ReadoptionState {
	switch r {
	case model.ReadoptionAwaiting:
		return adapterv1.ReadoptionState_READOPTION_STATE_AWAITING_ACCEPTANCE
	case model.ReadoptionInProgress:
		return adapterv1.ReadoptionState_READOPTION_STATE_IN_PROGRESS
	}
	return adapterv1.ReadoptionState_READOPTION_STATE_UNSPECIFIED
}

func ReadoptionFromProto(r adapterv1.ReadoptionState) model.Readoption {
	switch r {
	case adapterv1.ReadoptionState_READOPTION_STATE_AWAITING_ACCEPTANCE:
		return model.ReadoptionAwaiting
	case adapterv1.ReadoptionState_READOPTION_STATE_IN_PROGRESS:
		return model.ReadoptionInProgress
	}
	return model.ReadoptionNone
}

func SecondsFromDuration(d time.Duration) int64 { return int64(d / time.Second) }
func DurationFromSeconds(s int64) time.Duration { return time.Duration(s) * time.Second }

func DeviceStateToProto(s model.DeviceState) adapterv1.DeviceState {
	switch s {
	case model.DevicePending:
		return adapterv1.DeviceState_DEVICE_STATE_PENDING
	case model.DeviceAdopted:
		return adapterv1.DeviceState_DEVICE_STATE_ADOPTED
	}
	return adapterv1.DeviceState_DEVICE_STATE_UNSPECIFIED
}

func DeviceStateFromProto(s adapterv1.DeviceState) model.DeviceState {
	switch s {
	case adapterv1.DeviceState_DEVICE_STATE_PENDING:
		return model.DevicePending
	case adapterv1.DeviceState_DEVICE_STATE_ADOPTED:
		return model.DeviceAdopted
	}
	return ""
}

func WifiSecurityToProto(s model.WifiSecurity) adapterv1.WifiSecurity {
	switch s {
	case model.WifiOpen:
		return adapterv1.WifiSecurity_WIFI_SECURITY_OPEN
	case model.WifiWEP:
		return adapterv1.WifiSecurity_WIFI_SECURITY_WEP
	case model.WifiWPAPersonal:
		return adapterv1.WifiSecurity_WIFI_SECURITY_WPA_PERSONAL
	case model.WifiWPAEnterprise:
		return adapterv1.WifiSecurity_WIFI_SECURITY_WPA_ENTERPRISE
	}
	return adapterv1.WifiSecurity_WIFI_SECURITY_UNSPECIFIED
}

func WifiSecurityFromProto(s adapterv1.WifiSecurity) model.WifiSecurity {
	switch s {
	case adapterv1.WifiSecurity_WIFI_SECURITY_OPEN:
		return model.WifiOpen
	case adapterv1.WifiSecurity_WIFI_SECURITY_WEP:
		return model.WifiWEP
	case adapterv1.WifiSecurity_WIFI_SECURITY_WPA_PERSONAL:
		return model.WifiWPAPersonal
	case adapterv1.WifiSecurity_WIFI_SECURITY_WPA_ENTERPRISE:
		return model.WifiWPAEnterprise
	}
	return ""
}

func WifiBandToProto(b model.WifiBand) adapterv1.WifiBand {
	switch b {
	case model.BandBoth:
		return adapterv1.WifiBand_WIFI_BAND_BOTH
	case model.Band2G:
		return adapterv1.WifiBand_WIFI_BAND_2G
	case model.Band5G:
		return adapterv1.WifiBand_WIFI_BAND_5G
	}
	return adapterv1.WifiBand_WIFI_BAND_UNSPECIFIED
}

func WifiBandFromProto(b adapterv1.WifiBand) model.WifiBand {
	switch b {
	case adapterv1.WifiBand_WIFI_BAND_BOTH:
		return model.BandBoth
	case adapterv1.WifiBand_WIFI_BAND_2G:
		return model.Band2G
	case adapterv1.WifiBand_WIFI_BAND_5G:
		return model.Band5G
	}
	return ""
}
